import { Howl } from "howler";
import { assetUrl } from "../../core/AssetUrls";
import { AudioMixer } from "./AudioMixer";

/** One track of the soundtrack. The list below is the play order. */
export interface SoundtrackTrack {
  readonly title: string;
  readonly file: string;
}

/**
 * The soundtrack, in the order it plays. Five tracks, generated by Tom for
 * this game (2026-10-12) and shipped with the rest of `resources/` under
 * CC BY-SA 4.0; see CREDITS.md. They run as one cycle through the whole
 * session, the home page and the game alike, wrapping from the last back to
 * the first, and carrying on across the page loads in between.
 */
export const SOUNDTRACK: readonly SoundtrackTrack[] = [
  { title: "The Hegemon", file: "the-hegemon.mp3" },
  { title: "Dark Expanse", file: "dark-expanse.mp3" },
  { title: "Whispers of Rebellion", file: "whispers-of-rebellion.mp3" },
  { title: "Throne of Stars", file: "throne-of-stars.mp3" },
  { title: "The Fall", file: "the-fall.mp3" },
];

export function trackUrl(track: SoundtrackTrack): string {
  return assetUrl(`sounds/music/${track.file}`);
}

// An ease-in, not a swell. Long enough that the first track arrives rather
// than lands, short enough that the page is not still getting louder while
// the player reads it.
const FADE_IN_MS = 2000;

/**
 * Where the opening ramp starts, in dB below its target.
 *
 * This is driven here rather than through Howler's fade() because fade() is
 * linear in AMPLITUDE, and loudness is roughly linear in dB -- so a linear
 * ramp is heavily front-loaded and does not sound like a fade at all. At the
 * real defaults (music slider 0.5, squared by perceptualGain, times the -1 dB
 * trim, so a target of 0.2225) Howler's 0.01 quantisation gives 22 steps, and
 * the first two of them cover the bottom 21 dB:
 *
 *     90ms  0.01  -26.9 dB      989ms  0.11   -6.1 dB
 *    180ms  0.02  -20.9 dB     1438ms  0.16   -2.9 dB
 *    449ms  0.05  -13.0 dB     1978ms  0.22   -0.1 dB
 *
 * Within 6 dB of final at one second and 3 dB at 1.4s: the last 600ms are
 * inaudible and the track has perceptually arrived in about 300ms. Stepping
 * linearly in dB instead spends equal time on equal perceived change.
 *
 * -48 dB is low enough to start from true silence to the ear without wasting
 * the front of the ramp somewhere nothing is audible.
 */
const FADE_IN_FLOOR_DB = -48;

/**
 * How long the end of one track overlaps the start of the next.
 *
 * The crossfade is equal-power (cosine out, sine in) rather than the dB ramp
 * above: two dB-linear ramps crossing would both sit at -24 dB at the midpoint
 * and the sum would dip audibly, where cos²+sin² keeps the level flat. Four
 * seconds is long enough that the join reads as one piece of music giving way
 * to the next, short enough that a track's closing bars are not buried under
 * the next one's opening.
 */
export const CROSSFADE_MS = 4000;

// ~0.6 dB a step across the opening ramp: continuous to the ear, and cheap.
// Writing the volume directly also dodges the 0.01 quantisation Howler's own
// fade applies, which at this target would be 6 dB on the very first step.
const RAMP_STEP_MS = 25;

/**
 * How often the playing track is asked how far it has got. The crossfade
 * starts up to this late, which against four seconds is not audible; the
 * timer is also throttled in a hidden tab, and the "end" fallback below
 * covers a track that runs out before the poll catches it.
 */
export const POSITION_POLL_MS = 250;

/** Gain `t` of the way through the opening ramp, linear in dB. */
function rampGain(target: number, t: number): number {
  return target * 10 ** ((FADE_IN_FLOOR_DB * (1 - t)) / 20);
}

// ------------------------------------------------------------- persistence

/**
 * Where the position is kept between page loads: sessionStorage, which lives
 * as long as the tab does and no longer. Leaving a game for the home page is a
 * full navigation (`window.location.href = homeHref()`), as is a join that
 * lands on another server, and each one builds this player afresh -- which
 * used to mean the first track again every time, several times an evening for
 * a player knocked out of game after game. A fresh tab still opens on the top
 * of the list; a tab coming back to the home page picks up where it was.
 */
export const SOUNDTRACK_STORAGE_KEY = "darkstar.soundtrack";

interface SavedPosition {
  /** Index into SOUNDTRACK of the track that was playing. */
  readonly index: number;
  /** Seconds into it. */
  readonly position: number;
  /** Its length in seconds, or 0 while the stream had not reported one. */
  readonly duration: number;
}

/**
 * A track with less than a fade-in plus a crossfade left is not worth coming
 * back for: it would open from silence and be fading out again before it had
 * arrived. The next one starts clean instead.
 */
const RESUME_MIN_REMAINING_MS = FADE_IN_MS + CROSSFADE_MS;

function readSavedPosition(): SavedPosition | null {
  let raw: string | null;
  try {
    raw = sessionStorage.getItem(SOUNDTRACK_STORAGE_KEY);
  } catch {
    return null;
  }
  if (raw === null) return null;
  try {
    const parsed: unknown = JSON.parse(raw);
    if (typeof parsed !== "object" || parsed === null) return null;
    const { index, position, duration } = parsed as Record<string, unknown>;
    // The list may have changed between the build that wrote this and the
    // one reading it, so an index is only trusted inside the current list.
    if (typeof index !== "number" || !Number.isInteger(index)) return null;
    if (index < 0 || index >= SOUNDTRACK.length) return null;
    if (typeof position !== "number" || !Number.isFinite(position)) return null;
    if (position < 0) return null;
    const length =
      typeof duration === "number" && Number.isFinite(duration) && duration > 0
        ? duration
        : 0;
    return { index, position, duration: length };
  } catch {
    return null;
  }
}

function writeSavedPosition(saved: SavedPosition): void {
  try {
    sessionStorage.setItem(SOUNDTRACK_STORAGE_KEY, JSON.stringify(saved));
  } catch {
    // Storage unavailable or full: the music still plays, it just starts
    // over on the next page.
  }
}

/**
 * The soundtrack: the tracks of SOUNDTRACK one after another, each fading
 * into the next, wrapping round for as long as the page lives.
 *
 * One instance per page, created in Main.ts alongside the mixer, so the home
 * page, the lobby and the game are one continuous cycle: nothing cuts at the
 * map appearing, nothing restarts on the way back to the menu. Where the way
 * back IS a page load, the track and the position go through sessionStorage
 * (see SOUNDTRACK_STORAGE_KEY) and the new page's player resumes them, so the
 * cycle is the tab's rather than the page's. Browsers block audio until a user
 * gesture, so the first track starts inside the first pointerdown/keydown; a
 * game started by URL asks for it from ClientGameRunner.start(), which lands
 * after a click of its own.
 *
 * Every track streams (html5) rather than decoding megabytes up front; the
 * next one is constructed as soon as the current one starts, so its fetch is
 * under way long before the crossfade needs it.
 *
 * Levels: the opening ramp and the crossfades are driven here, reading the
 * music channel on every step so the slider and the focus duck reach a track
 * while it is still moving. A track is handed to the mixer only once it has
 * landed at full level, which is the only place it is registered; the mixer
 * writes the channel volume straight onto a registered Howl, so one that is
 * mid-ramp cannot be registered or the two would fight.
 */
export class Soundtrack {
  /** Index into SOUNDTRACK of `current`, or of the next track to start. */
  private index = 0;
  /**
   * Seconds into the track at `index` to start from: where the previous page
   * left it, or 0. Cleared once playback has really started there, so a play
   * the autoplay rule blocked still resumes on the gesture that follows.
   */
  private resumeAt = 0;
  /** The track being heard, or on its way in. Null until the first start. */
  private current: Howl | null = null;
  /** The track after `current`, constructed early so it is buffering. */
  private next: Howl | null = null;
  /** Tears down the ramp in flight, if any. */
  private ramp: (() => void) | null = null;
  private poll: ReturnType<typeof setInterval> | null = null;
  /** Consecutive tracks that failed to load; stops a dead CDN spinning. */
  private loadFailures = 0;
  private disposed = false;

  constructor(private readonly mixer: AudioMixer) {
    this.restore();
    window.addEventListener("pagehide", this.onPageHide);
    this.arm();
  }

  /**
   * Starts the soundtrack if it is not already playing. Idempotent, so both
   * the home page's first gesture and a game's start can call it freely.
   */
  play(): void {
    if (this.disposed || this.current !== null) return;
    this.disarm();
    const howl = this.next ?? this.load(this.index);
    this.next = null;
    if (howl === null) return;
    this.current = howl;
    // Howler queues a seek on a stream that has not loaded and applies it
    // before the queued play, so the first sample heard is the resumed one.
    if (this.resumeAt > 0) {
      const at = this.resumeAt;
      this.safely("seek track", () => howl.seek(at));
    }
    this.begin(howl, this.index, () => this.fadeIn(howl));
    howl.play();
  }

  dispose(): void {
    this.disposed = true;
    window.removeEventListener("pagehide", this.onPageHide);
    this.disarm();
    this.cancelRamp();
    this.stopPoll();
    for (const howl of [this.current, this.next]) {
      if (howl === null) continue;
      this.mixer.unregister(howl);
      this.safely("stop track", () => howl.stop());
      this.safely("unload track", () => howl.unload());
    }
    this.current = null;
    this.next = null;
  }

  // ------------------------------------------------------------ gestures

  /**
   * Removing first keeps arm() idempotent, so a second call cannot stack a
   * duplicate; both listeners come off together, because `once` only removes
   * the one that fired and the other would otherwise start a second copy.
   */
  private arm(): void {
    this.disarm();
    document.addEventListener("pointerdown", this.onGesture, { once: true });
    document.addEventListener("keydown", this.onGesture, { once: true });
  }

  private disarm(): void {
    document.removeEventListener("pointerdown", this.onGesture);
    document.removeEventListener("keydown", this.onGesture);
  }

  private readonly onGesture = () => this.play();

  // ------------------------------------------------------------- position

  /** Picks up where the previous page in this tab left the soundtrack. */
  private restore(): void {
    const saved = readSavedPosition();
    if (saved === null) return;
    const remainingMs = (saved.duration - saved.position) * 1000;
    if (saved.duration > 0 && remainingMs <= RESUME_MIN_REMAINING_MS) {
      this.index = (saved.index + 1) % SOUNDTRACK.length;
      return;
    }
    this.index = saved.index;
    this.resumeAt = saved.position;
  }

  /**
   * Records where the playing track has got to. Called from every poll tick,
   * so the record is at most POSITION_POLL_MS stale on a normal navigation,
   * and from pagehide for a hidden tab whose timers were held back.
   */
  private save(howl: Howl): void {
    const duration = howl.duration();
    const position: unknown = howl.seek();
    if (typeof position !== "number" || !Number.isFinite(position)) return;
    writeSavedPosition({
      index: this.index,
      position,
      duration: duration > 0 && Number.isFinite(duration) ? duration : 0,
    });
  }

  private readonly onPageHide = () => {
    if (this.current !== null) this.save(this.current);
  };

  // -------------------------------------------------------------- tracks

  private load(index: number): Howl | null {
    const track = SOUNDTRACK[index];
    try {
      const howl = new Howl({
        src: [trackUrl(track)],
        loop: false,
        // Silent until a ramp writes a level. Howler defaults to 1.
        volume: 0,
        // Stream rather than decode 2-4 MB up front -- the first track starts
        // on the player's first click, so the wait would land right when they
        // are trying to use the page. Cues and ambience stay on Web Audio.
        html5: true,
      });
      // Bound without an id: Howler emits loaderror with a null id for a
      // failed fetch, and an id-bound listener would never see it.
      howl.once("loaderror", () => this.onLoadError(howl, index));
      return howl;
    } catch (error) {
      console.warn(`Soundtrack: failed to load ${track.file}`, error);
      return null;
    }
  }

  /**
   * Arms what happens when `howl` actually starts playing, and the fallbacks
   * for it never doing so. Must be called before play().
   *
   * play() on a Howl that has not loaded yet queues itself and returns at
   * once, so the call tells us nothing about when the first sample lands. For
   * an html5 stream the gap is a network fetch: a few hundred ms warm, and on
   * a slow connection longer than the whole ramp -- in which case timing from
   * the call would have the track arrive at full level with no fade at all.
   * Howler emits "play" when the media element's own play() promise resolves,
   * which is playback actually starting.
   */
  private begin(howl: Howl, index: number, onStarted: () => void): void {
    const onPlay = () => {
      howl.off("playerror", onPlayError);
      if (this.current !== howl) return;
      this.loadFailures = 0;
      // Written now, ahead of the first poll, so a page that leaves during
      // the opening seconds still knows which track it was on.
      writeSavedPosition({ index, position: this.resumeAt, duration: 0 });
      this.resumeAt = 0;
      // The one after this starts buffering now, so the crossfade finds it
      // ready. One ahead only: two streams is the most ever in flight.
      this.next = this.load((index + 1) % SOUNDTRACK.length);
      howl.once("end", () => this.onEnded(howl));
      onStarted();
      this.startPoll(howl);
    };
    // Playback never started -- most often the autoplay rule, when a game
    // opened by URL asked before any gesture. Let the track go and listen for
    // a gesture again, rather than leave a Howl that nothing owns.
    const onPlayError = () => {
      howl.off("play", onPlay);
      if (this.current !== howl) return;
      this.drop(howl);
      this.current = null;
      this.arm();
    };
    howl.once("play", onPlay);
    howl.once("playerror", onPlayError);
  }

  /**
   * A track that would not load is skipped. The file could be missing or the
   * CDN could be blipping; either way the next one is the best thing to try,
   * up to one full lap, after which the soundtrack falls silent rather than
   * fetching five files forever.
   */
  private onLoadError(howl: Howl, index: number): void {
    this.loadFailures++;
    if (howl === this.next) {
      this.next = null;
      this.drop(howl);
      return;
    }
    if (howl !== this.current) return;
    this.cancelRamp();
    this.stopPoll();
    this.mixer.unregister(howl);
    this.drop(howl);
    this.current = null;
    if (this.loadFailures >= SOUNDTRACK.length) return;
    this.index = (index + 1) % SOUNDTRACK.length;
    this.play();
  }

  private drop(howl: Howl): void {
    this.safely("stop track", () => howl.stop());
    this.safely("unload track", () => howl.unload());
  }

  // --------------------------------------------------------------- levels

  /**
   * Hands a track to the mixer once a ramp is done with it. Registering
   * writes the channel volume straight onto the Howl, so it also lands the
   * ramp exactly on target.
   */
  private settle(howl: Howl): void {
    this.cancelRamp();
    this.mixer.register(howl, "music");
  }

  private cancelRamp(): void {
    this.ramp?.();
    this.ramp = null;
  }

  /**
   * Runs `step(t)` every RAMP_STEP_MS with t climbing from 0 to 1 over
   * `durationMs`, then `done`. Driven off elapsed time rather than a tick
   * count: a backgrounded tab throttles timers hard, and the ramp should
   * still finish on schedule with coarser steps rather than stretch out.
   */
  private runRamp(
    durationMs: number,
    step: (t: number) => void,
    done: () => void,
  ): void {
    this.cancelRamp();
    const startedAt = performance.now();
    step(0);
    const timer = setInterval(() => {
      const t = Math.min(1, (performance.now() - startedAt) / durationMs);
      if (t >= 1) {
        done();
        return;
      }
      step(t);
    }, RAMP_STEP_MS);
    this.ramp = () => clearInterval(timer);
  }

  /** The opening ramp, from silence, in even dB steps. */
  private fadeIn(howl: Howl): void {
    // Nothing to hear and nothing to ramp on a channel the player has turned
    // off, so hand it over rather than run an interval writing zero eighty
    // times. Registered, the mixer brings it up if music comes back.
    //
    // isAudible, not volumeFor: the question is whether the channel is
    // genuinely silent, not whether it happens to be silent this instant.
    // volumeFor folds in the focus duck, so asking it here would skip the
    // ramp for a play that landed while the page was unfocused -- the track
    // would then arrive at full level on refocus. A ducked channel still
    // ramps; the tick writes it silent and hands it back in position.
    if (!this.mixer.isAudible("music")) {
      this.settle(howl);
      return;
    }
    this.runRamp(
      FADE_IN_MS,
      // The target is read every step, so `t` is only ever the ramp's own
      // position in dB and the level it scales is always the current one. A
      // mute lands within a step; the focus duck takes the track to silence
      // and gives it back at the position the ramp has meanwhile reached; a
      // slider tracks continuously. None of them restarts the ramp.
      (t) => howl.volume(rampGain(this.mixer.volumeFor("music"), t)),
      () => this.settle(howl),
    );
  }

  /**
   * Equal-power crossfade from `outgoing` into `incoming`, which has just
   * started. Neither is registered while it runs: the mixer would otherwise
   * stamp the channel level over the curve on every slider move.
   */
  private crossfade(outgoing: Howl, incoming: Howl): void {
    const finish = () => {
      this.drop(outgoing);
      this.settle(incoming);
    };
    if (!this.mixer.isAudible("music")) {
      finish();
      return;
    }
    this.runRamp(
      CROSSFADE_MS,
      (t) => {
        const target = this.mixer.volumeFor("music");
        const phase = (t * Math.PI) / 2;
        outgoing.volume(target * Math.cos(phase));
        incoming.volume(target * Math.sin(phase));
      },
      finish,
    );
  }

  // ------------------------------------------------------------ advancing

  /**
   * Watches the playing track's position and starts the crossfade when
   * CROSSFADE_MS remain. Howler's seek() hands back the Howl rather than a
   * number while the stream is loading or play-locked, and duration() is 0
   * until the metadata arrives, so both are checked before they are trusted.
   */
  private startPoll(howl: Howl): void {
    this.stopPoll();
    this.poll = setInterval(() => {
      if (this.current !== howl) {
        this.stopPoll();
        return;
      }
      const duration = howl.duration();
      // Typed as a number, but the Howl comes back while play-locked.
      const position: unknown = howl.seek();
      if (typeof position !== "number") return;
      if (!(duration > 0) || !Number.isFinite(duration)) return;
      this.save(howl);
      if ((duration - position) * 1000 <= CROSSFADE_MS) {
        this.stopPoll();
        this.advance(howl, "crossfade");
      }
    }, POSITION_POLL_MS);
  }

  private stopPoll(): void {
    if (this.poll === null) return;
    clearInterval(this.poll);
    this.poll = null;
  }

  /**
   * The track ran out before the poll caught it: no duration from the stream,
   * or a hidden tab's timers held back for a minute. There is nothing left to
   * fade out of, so the next one opens from silence on the usual ramp.
   */
  private onEnded(howl: Howl): void {
    if (this.current !== howl) {
      // An outgoing track running out mid-crossfade is the ramp's to drop
      // when it finishes; one that nothing is fading any more is nobody's.
      if (this.ramp === null) this.drop(howl);
      return;
    }
    this.stopPoll();
    this.advance(howl, "fade-in");
  }

  private advance(outgoing: Howl, join: "crossfade" | "fade-in"): void {
    this.cancelRamp();
    this.mixer.unregister(outgoing);
    this.index = (this.index + 1) % SOUNDTRACK.length;
    const incoming = this.next ?? this.load(this.index);
    this.next = null;
    if (incoming === null) {
      this.drop(outgoing);
      this.current = null;
      return;
    }
    this.current = incoming;
    // A track that has run out has nothing left to give; one still playing
    // stays up until the incoming track is really sounding under it.
    if (join === "fade-in") this.drop(outgoing);
    this.begin(incoming, this.index, () => {
      if (join === "crossfade") this.crossfade(outgoing, incoming);
      else this.fadeIn(incoming);
    });
    incoming.play();
  }

  private safely(action: string, fn: () => void): void {
    try {
      fn();
    } catch (error) {
      console.error(`Soundtrack: failed to ${action}`, error);
    }
  }
}

let instance: Soundtrack | null = null;

/** Created once, from Main.ts, right after the mixer. */
export function initSoundtrack(mixer: AudioMixer): Soundtrack {
  instance?.dispose();
  instance = new Soundtrack(mixer);
  return instance;
}

/** Null until initSoundtrack runs -- component tests mount without it. */
export function soundtrack(): Soundtrack | null {
  return instance;
}

/** Test seam: drops the singleton so each case starts clean. */
export function resetSoundtrackForTest(): void {
  instance?.dispose();
  instance = null;
}
